 void fileOptions(Store.Job j){String[] choices={tr("إعادة التسمية","Rename"),tr("حذف الملف","Delete file"),tr("معلومات الملف","Details"),tr("فحص البصمة الرقمية","Verify SHA-256"),tr("تحرير الوسائط","Edit media"),tr("تشغيل داخل التطبيق","Play in X Download"),tr("فتح بتطبيق آخر","Open in another app"),tr("نسخ إلى مكان آخر","Copy to another location"),j.favorite?tr("إزالة من المفضلة","Remove favorite"):tr("إضافة للمفضلة","Add favorite")};new AlertDialog.Builder(this).setTitle(j.name).setItems(choices,(d,w)->{if(w==0){EditText name=new EditText(this);name.setSingleLine(true);name.setText(j.name);new AlertDialog.Builder(this).setTitle(tr("إعادة تسمية","Rename")).setView(name).setPositiveButton("OK",(x,y)->{String newName=HttpEngine.safeName(name.getText().toString());String ext=j.name.lastIndexOf('.')>=0?j.name.substring(j.name.lastIndexOf('.')):"";if(!ext.isEmpty()&&!newName.toLowerCase(java.util.Locale.ROOT).endsWith(ext.toLowerCase(java.util.Locale.ROOT)))newName+=ext;ContentValues v=new ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,newName);try{Uri renamed=DownloadDestination.rename(this,Uri.parse(j.uri),newName);j.uri=renamed.toString();j.name=DownloadDestination.name(this,renamed,newName);store.save();downloads(true);}catch(Exception e){note(tr("تعذر تغيير الاسم","Rename failed"));}}).setNegativeButton("Cancel",null).show();}
 else if(w==1)new AlertDialog.Builder(this).setMessage(tr("حذف هذا الملف نهائيًا؟","Permanently delete this file?")).setPositiveButton(tr("حذف","Delete"),(x,y)->{try{DownloadDestination.delete(this,Uri.parse(j.uri));store.remove(j);downloads(true);}catch(Exception e){note(tr("تعذر الحذف","Delete failed"));}}).setNegativeButton("Cancel",null).show();
 else if(w==2){int duplicates=0;for(Store.Job other:store.list())if(other!=j&&!j.sha.isEmpty()&&j.sha.equals(other.sha)&&other.state.equals("complete"))duplicates++;new AlertDialog.Builder(this).setTitle(j.name).setMessage(j.mime+"\n"+size(j.total)+"\nSHA-256: "+j.sha+"\n"+tr("نسخ مطابقة مسجلة: ","Matching registered copies: ")+duplicates).setPositiveButton("OK",null).show();}
 else if(w==3){io.execute(()->{try(InputStream in=getContentResolver().openInputStream(Uri.parse(j.uri))){if(in==null)throw new IOException("Missing file");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)digest.update(buf,0,n);StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));String value=hash.toString();h.post(()->{if(!closed)new AlertDialog.Builder(this).setTitle(value.equalsIgnoreCase(j.sha)?tr("البصمة مطابقة","Checksum matches"):tr("البصمة مختلفة أو غير مسجلة","Checksum differs or not recorded")).setMessage(value).setPositiveButton("OK",null).show();});}catch(Exception e){h.post(()->{if(!closed)note("Unable to verify file");});}});}
 else if(w==4){if(j.mime.startsWith("audio/")||j.mime.startsWith("video/"))startActivity(new Intent(this,ExportActivity.class).setData(Uri.parse(j.uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));else note(tr("الملف ليس وسائط","Not an audio/video file"));}else if(w==5){if(LocalPlayerActivity.playable(j))playLocal(j);else note(tr("الملف ليس وسائط","Not an audio/video file"));}else if(w==6)open(j,false);else if(w==7)copyFile(j);else if(w==8){j.favorite=!j.favorite;store.save();downloads(true);}}).setNegativeButton("Cancel",null).show();}
 static boolean canRenew(Store.Job j){return j!=null&&!j.torrent&&j.selector.isEmpty()&&(j.state.equals("error")||j.state.equals("paused"));}
 void renewLink(Store.Job old){if(!canRenew(old))return;EditText input=field(tr("رابط جديد مصرح به","New authorized link"));new AlertDialog.Builder(this).setTitle(tr("تجديد الرابط","Renew link")).setMessage(tr("سيتم فحص الرابط الجديد. يبدأ ملف جديد من الصفر دون دمج أجزاء غير متحققة، ويظل التحميل القديم محفوظًا.","New link is checked. A separate download starts from zero; old partial data is kept and never mixed.")).setView(input).setPositiveButton(tr("فحص","Check"),(d,w)->{final String url;try{url=extract(input.getText().toString());}catch(Exception ex){note(tr("رابط غير صالح","Invalid URL"));return;}if(url.equals(old.url)){note(tr("هذا هو الرابط القديم","This is the previous URL"));return;}boolean http=prefs.getBoolean("http",false);io.execute(()->{try{HttpEngine.Info info=HttpEngine.probe(url,http);if(HttpEngine.html(info.mime)||HttpEngine.manifest(info.name,info.mime))throw new IOException("Not a direct file");h.post(()->{if(closed)return;new AlertDialog.Builder(this).setTitle(tr("تحميل مستقل","New download")).setMessage(info.name+" • "+(info.size<0?tr("الحجم غير معروف","Unknown size"):size(info.size))+"\n"+tr("سيتم الاحتفاظ بالبصمة المتوقعة إن وجدت. تأكد أنه نفس المحتوى.","Expected checksum, if set, is retained. Verify this is the intended content.")).setPositiveButton(tr("بدء","Start"),(a,b)->{if(!canRenew(old)){note(tr("تغيرت حالة التحميل القديم","Previous download state changed"));return;}Store.Job replacement=new Store.Job(url,info,old.expected);replacement.priority=old.priority;store.add(replacement);send("start",replacement.id);show(2);}).setNegativeButton(tr("إلغاء","Cancel"),null).show();});}catch(Exception ex){h.post(()->{if(!closed)note(tr("فشل فحص الرابط الجديد","New URL check failed"));});}});}).setNegativeButton(tr("إلغاء","Cancel"),null).show();}
 void chooseDestination(){String selected=prefs.getString("download_tree","");new AlertDialog.Builder(this).setTitle(tr("مكان الحفظ","Download destination")).setMessage((selected.isEmpty()?tr("مجلد Downloads الافتراضي","Default Downloads folder"):tr("مجلد مخصص: ","Custom folder: ")+DownloadDestination.label(this,Uri.parse(selected)))+"\n"+tr("يطبق عند حفظ التحميلات الجديدة أو المستأنفة. الملفات السابقة لا تنتقل.","Applies when publishing new or resumed downloads. Existing files are not moved.")).setItems(new String[]{tr("اختيار مجلد / كارت ذاكرة","Choose folder / SD card"),tr("استعادة مجلد Downloads الافتراضي","Restore default Downloads")},(d,w)->{if(w==0){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION),37);}catch(RuntimeException ex){note(tr("منتقي المجلدات غير متاح","Folder picker unavailable"));}}else{prefs.edit().remove("download_tree").apply();note(tr("تم استعادة المجلد الافتراضي","Default folder restored"));}}).setNegativeButton(tr("إلغاء","Cancel"),null).show();}
 void copyFile(Store.Job j){copySource=j;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(j.mime).putExtra(Intent.EXTRA_TITLE,j.name),36);}catch(Exception e){copySource=null;note(tr("لا يوجد مدير ملفات مناسب","No document picker"));}}
 void copyTo(Uri dest,Store.Job job){if(dest.toString().equals(job.uri)){note(tr("اختر مكانًا مختلفًا","Choose a different destination"));return;}io.execute(()->{try(InputStream in=getContentResolver().openInputStream(Uri.parse(job.uri));OutputStream out=getContentResolver().openOutputStream(dest,"w")){AudioStudioActivity.copy(in,out);h.post(()->{if(!closed)note(tr("تم النسخ. الأصل محفوظ","Copied. Original kept."));});}catch(Exception ex){h.post(()->{if(!closed)note(tr("تعذر النسخ؛ تحقق من الملف الناتج","Copy failed; check the destination file"));});}});}
 void open(Store.Job j,boolean share){Uri u=Uri.parse(j.uri);Intent i=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(share)i.setType(j.mime).putExtra(Intent.EXTRA_STREAM,u);else i.setDataAndType(u,j.mime);i.setClipData(ClipData.newRawUri("Download",u));try{startActivity(Intent.createChooser(i,"Choose app"));}catch(Exception e){note("No compatible app");}}
