 void confirmTorrent(String magnet,Uri uri){new AlertDialog.Builder(this).setTitle("BitTorrent").setMessage(tr("استخدم ملفات مسموحًا بمشاركتها فقط. التورنت يشارك بيانات مع الأقران ويكشف عنوان IP لهم. الملفات المتعددة تُحفظ كأرشيف ZIP. هل تريد المتابعة؟","Use only authorized files. BitTorrent uploads pieces to peers and exposes your IP to them. Multi-file torrents export as a ZIP archive. Continue?")).setPositiveButton(tr("تحميل","Download"),(d,w)->{Store.Job j=new Store.Job(magnet==null?"torrent:local":magnet,new HttpEngine.Info("Torrent","application/octet-stream",-1,"","",false),"");j.torrent=true;if(uri==null){store.add(j);send("start",j.id);show(2);}else io.execute(()->{try{TorrentEngine.importFile(this,uri,j);h.post(()->{if(!closed){store.add(j);send("start",j.id);show(2);}else TorrentEngine.cleanup(this,j.id);});}catch(Exception e){h.post(()->{if(!closed)note(String.valueOf(e.getMessage()));});}});}).setNegativeButton("Cancel",null).show();}
