 static void filterSettings(LinearLayout list,String query){String q=query.trim().toLowerCase(Locale.ROOT);for(int i=2;i<list.getChildCount();i++){View v=list.getChildAt(i);String label=v instanceof TextView?((TextView)v).getText().toString().toLowerCase(Locale.ROOT):"";v.setVisibility(q.isEmpty()||label.contains(q)?View.VISIBLE:View.GONE);}}
 void diagnostics(){ActivityManager am=getSystemService(ActivityManager.class);ActivityManager.MemoryInfo mem=new ActivityManager.MemoryInfo();am.getMemoryInfo(mem);PowerManager power=getSystemService(PowerManager.class);android.net.ConnectivityManager network=getSystemService(android.net.ConnectivityManager.class);int active=0,errors=0,complete=0;for(Store.Job j:store.list()){if(isActive(j))active++;if(j.state.equals("error"))errors++;if(j.state.equals("complete"))complete++;}String msg=Build.MANUFACTURER+" "+Build.MODEL+"\nAndroid "+Build.VERSION.RELEASE+"\n"+tr("مساحة خالية: ","Free storage: ")+size(getFilesDir().getUsableSpace())+"\n"+tr("ذاكرة النظام المتاحة: ","Available system RAM: ")+size(mem.availMem)+"\n"+tr("ضغط الذاكرة: ","Memory pressure: ")+mem.lowMemory+"\n"+tr("حالة الحرارة: ","Thermal status: ")+power.getCurrentThermalStatus()+"\n"+tr("توفير البطارية: ","Battery saver: ")+power.isPowerSaveMode()+"\n"+tr("شبكة محدودة: ","Metered network: ")+network.isActiveNetworkMetered()+"\n"+tr("نشطة أو في الانتظار: ","Active or waiting: ")+active+"\n"+tr("أخطاء مسجلة: ","Recorded errors: ")+errors+"\n"+tr("مكتملة: ","Completed: ")+complete+"\n"+tr("الإشعارات: ","Notifications: ")+getSystemService(NotificationManager.class).areNotificationsEnabled();new AlertDialog.Builder(this).setTitle(tr("تشخيص محلي","Local diagnostics")).setMessage(msg).setPositiveButton("OK",null).show();}
