 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==37){if(result==RESULT_OK&&data!=null&&data.getData()!=null){try{DownloadDestination.select(this,data);note(tr("تم اختيار المجلد","Folder selected"));}catch(Exception ex){note(tr("المجلد لا يمنح صلاحية حفظ دائمة","Folder does not grant persistent write access"));}}return;}if(req==36){Store.Job source=copySource;copySource=null;if(source!=null&&result==RESULT_OK&&data!=null&&data.getData()!=null)copyTo(data.getData(),source);return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();if(req==35){confirmTorrent(null,u);return;}if(req==34){startActivity(new Intent(this,ExportActivity.class).setData(u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));return;}io.execute(()->{try{if(req==31){inspect(u);return;}String[] keys={"english","light","wifi","battery","http","js","block_trackers","data_saver"};if(req==32){JSONObject j=new JSONObject();for(String k:keys)if(prefs.contains(k))j.put(k,prefs.getBoolean(k,false));j.put("schema",2);j.put("mode",prefs.getInt("mode",1));j.put("rate_kib",prefs.getInt("rate_kib",0));j.put("global_http_kib",prefs.getInt("global_http_kib",0));j.put("parallel_jobs",prefs.getInt("parallel_jobs",2));j.put("connections",prefs.getInt("connections",8));j.put("search_engine",prefs.getInt("search_engine",0));j.put("player_repeat",prefs.getInt("player_repeat",0));j.put("player_speed",prefs.getInt("player_speed",100));try(OutputStream out=getContentResolver().openOutputStream(u,"w")){if(out==null)throw new IOException();out.write(j.toString(2).getBytes("UTF-8"));}}else if(req==33){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>16384)throw new IOException("Backup too large");out.write(b,0,n);}}JSONObject j=new JSONObject(out.toString("UTF-8"));SharedPreferences.Editor e=prefs.edit();for(String k:keys)if(j.opt(k) instanceof Boolean)e.putBoolean(k,j.getBoolean(k));restoreInt(j,e,"mode",0,3);restoreInt(j,e,"rate_kib",0,102400);restoreInt(j,e,"global_http_kib",0,102400);restoreInt(j,e,"parallel_jobs",1,3);restoreInt(j,e,"connections",1,32);restoreInt(j,e,"search_engine",0,2);restoreInt(j,e,"player_repeat",0,2);restoreInt(j,e,"player_speed",50,200);e.apply();}h.post(()->{if(!closed){if(req==33){for(WebView w:tabs){w.getSettings().setJavaScriptEnabled(prefs.getBoolean("js",true));w.getSettings().setBlockNetworkImage(prefs.getBoolean("data_saver",false));}setup();}note("OK");}});}catch(Exception e){h.post(()->{if(!closed)note(e.getMessage());});}});}
 static void restoreInt(JSONObject j,SharedPreferences.Editor e,String key,int min,int max){Object value=j.opt(key);if(value instanceof Number){double v=((Number)value).doubleValue();if(Double.isFinite(v)&&v==Math.rint(v)&&v>=min&&v<=max)e.putInt(key,(int)v);}}
 void inspect(Uri u)throws Exception{File f=File.createTempFile("inspect-",".apk",getCacheDir());try{try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("Cannot read");byte[] b=new byte[65536];int n;long size=0;while((n=in.read(b))!=-1){size+=n;if(size>200000000L)throw new IOException("Inspection limit: 200 MB");out.write(b,0,n);}}PackageInfo p=getPackageManager().getPackageArchiveInfo(f.getPath(),PackageManager.GET_PERMISSIONS|PackageManager.GET_SIGNING_CERTIFICATES);if(p==null)throw new IOException("Invalid APK");StringBuilder s=new StringBuilder(p.packageName+"\nVersion: "+p.versionName+"\nMin Android API: "+p.applicationInfo.minSdkVersion+"\nSHA-256: "+HttpEngine.sha256(f));if(p.signingInfo!=null)for(android.content.pm.Signature sig:p.signingInfo.getApkContentsSigners()){s.append("\nCertificate SHA-256: ");for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(sig.toByteArray()))s.append(String.format(Locale.US,"%02x",b&255));}s.append("\nPermissions:\n");if(p.requestedPermissions!=null)for(String perm:p.requestedPermissions)s.append(perm).append('\n');s.append("\nMetadata only; not malware detection.");h.post(()->{if(!closed)new AlertDialog.Builder(this).setTitle("APK inspection").setMessage(s.toString()).setPositiveButton("OK",null).show();});}finally{f.delete();}}
 static String size(long b){double n=Math.max(0,b);String[] u={"B","KB","MB","GB","TB"};int i=0;while(n>=1000&&i<u.length-1){n/=1000;i++;}return String.format(Locale.US,i>0&&n<10?"%.1f %s":"%.0f %s",n,u[i]);}
 void receive(Intent i){if(i==null)return;if(!screenAccessAllowed()){deferredIntent=i;return;}if(i.getBooleanExtra("resume_due",false)){i.removeExtra("resume_due");show(2);for(Store.Job j:store.list())if(j.state.equals("scheduled")&&j.notBefore<=System.currentTimeMillis()){send("start",j.id);break;}return;}if(i.getBooleanExtra("downloads",false)){show(2);return;}if(Intent.ACTION_SEND.equals(i.getAction())){CharSequence s=i.getCharSequenceExtra(Intent.EXTRA_TEXT);if(s!=null){pending=s.toString();show(0);h.post(()->{if(!closed)analyze(s.toString());});}}}
